import React, { useEffect, useState } from "react";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { useNavigate, useLocation } from "react-router-dom";
import { IconButton } from "@mui/material";
import http from "../../services/utility";
import { apisPath } from "../../utils/path";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { useDispatch } from "react-redux";

export default function EditPlan() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { state } = useLocation();
  const [editable, setEditable] = useState(state?.editable);
  const [stateData, setStateData] = useState(state?.data);

  const [formData, setFormData] = useState({
    duration: editable ? stateData?.duration : "",
    price: editable ? stateData?.price : "",
    benefits: editable ? stateData?.benefits : [""],
  });

  // useEffect(() => {
  //   if (typeof formData?.benefits === "object") {
  //     let data = { ...formData };
  //     data["benefits"] = data?.benefits?.join("\n");
  //     setFormData(data);
  //   }
  // }, []);

  const uploadData = async (e) => {
    let data = { ...formData };
    await http
      .post(apisPath?.admin?.plans, data)
      .then((res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        navigate(-1);
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const updateData = async () => {
    let data = { ...formData };
    await http
      .put(`${apisPath?.admin?.plans}/${state?.data?.id}`, data)
      .then(async (res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        navigate(-1);
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const deleteData = async () => {
    await http
      .delete(`${apisPath?.admin?.plans}/${state?.data?.id}`)
      .then(async (res) => {
        // console.log(res?.data?.message);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        navigate(-1);
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const handleInputChange = (e) => {
    const { name, value } = e?.target;

    setFormData((prev) => {
      return { ...prev, [name]: value };
    });
  };

  const handleInput1Change = (index, e) => {
    const { value } = e?.target;
    let form = { ...formData };
    form.benefits[index] = value;
    setFormData(form);
  };

  return (
    <div className="edit_plan">
      <div className="detail__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">Edit plan</h3>
      </div>
      <div className="edit_plan__content">
        <div className="edit_plan__content__plan_duration">
          <label htmlFor="duration">Plan duration</label>
          <input
            type="text"
            id="duration"
            name="duration"
            placeholder="Enter here"
            value={formData?.duration}
            onChange={handleInputChange}
          />
        </div>
        <div className="edit_plan__content__price">
          <label htmlFor="price">Price</label>
          <input
            type="text"
            id="price"
            name="price"
            placeholder="Enter here"
            value={formData?.price}
            onChange={handleInputChange}
          />
        </div>
        <div className="edit_plan__content__benefits">
          <label htmlFor="benefits">Benefits</label>
          <div className="edit_plan__content__benefits__content">
            {formData?.benefits?.map((benefit, index) => {
              return (
                <input
                  id="benefits"
                  name="benefits"
                  placeholder="Enter here"
                  value={benefit}
                  onChange={(e) => handleInput1Change(index, e)}
                />
              );
            })}
            <button
              className="button-red"
              onClick={() => {
                let form = { ...formData };
                form.benefits.push("");
                setFormData(form);
              }}
            >
              Add Benefits
            </button>
          </div>
        </div>
        <button
          className="button-red"
          onClick={editable ? updateData : uploadData}
        >
          Done
        </button>
        <button className="button-border-red" onClick={deleteData}>
          Delete
        </button>
      </div>
    </div>
  );
}
